<?php
declare(strict_types=1); namespace Wms;
final class UserService extends Service {
 public function handle(string$a,array$p,array$u):array{if($u['role']!=='admin')throw new ApiException('FORBIDDEN','Недостаточно прав',403);if($a==='list'){[$page,$size,$offset]=Util::page($p);$total=(int)$this->db->one('SELECT COUNT(*) n FROM users WHERE deleted_at IS NULL')['n'];$rows=$this->db->all('SELECT id,login,display_name,role,active,created_at,last_login,version FROM users WHERE deleted_at IS NULL ORDER BY created_at DESC LIMIT ? OFFSET ?',[$size,$offset]);return['items'=>array_map(fn($x)=>$this->camel($x),$rows),'page'=>$page,'pageSize'=>$size,'total'=>$total,'pages'=>(int)ceil($total/$size)];}if($a==='create')return$this->create($p,$u);return$this->mutate($a,$p,$u);}
 private function create(array$p,array$u):array{$login=strtolower(Util::text($p['login']??''));if(!preg_match('/^[a-z][a-z0-9._-]{2,31}$/',$login))throw new ApiException('VALIDATION','Логин: 3–32 латинских символа, цифры, точка, дефис или подчёркивание');if(strlen((string)($p['password']??''))<8)throw new ApiException('VALIDATION','Пароль должен содержать не менее 8 символов');if($this->db->one('SELECT id FROM users WHERE login=?',[$login]))throw new ApiException('DUPLICATE','Логин уже используется');$id=Util::uuid();$row=['id'=>$id,'login'=>$login,'displayName'=>Util::text($p['displayName']??''),'role'=>($p['role']??'')==='admin'?'admin':'warehouse','active'=>true,'version'=>1];$this->db->exec('INSERT INTO users(id,login,password_hash,display_name,role,active,created_at) VALUES(?,?,?,?,?,?,?)',[$id,$login,password_hash((string)$p['password'],PASSWORD_DEFAULT),$row['displayName'],$row['role'],1,Util::now()]);$this->audit->log($u,'CREATE','user',$id,[],$row);return$row;}
 private function mutate(string$a,array$p,array$u):array{$r=$this->one('SELECT * FROM users WHERE id=? AND deleted_at IS NULL',[$p['id']??''],'Пользователь не найден');return$this->db->transaction(function()use($a,$p,$u,$r){if($a==='update'){$fields=[Util::text($p['displayName']??''),($p['role']??'')==='admin'?'admin':'warehouse',Util::bool($p['active']??false)?1:0];$sql='UPDATE users SET display_name=?,role=?,active=?,version=version+1';if(!empty($p['password'])){if(strlen((string)$p['password'])<8)throw new ApiException('VALIDATION','Пароль должен содержать не менее 8 символов');$sql.=',password_hash=?';$fields[]=password_hash((string)$p['password'],PASSWORD_DEFAULT);}$sql.=' WHERE id=? AND version=?';array_push($fields,$r['id'],(int)$p['version']);$this->conflict($this->db->exec($sql,$fields));if(!$fields[2])$this->db->exec('UPDATE sessions SET revoked_at=? WHERE user_id=? AND revoked_at IS NULL',[Util::now(),$r['id']]);$this->audit->log($u,'UPDATE','user',$r['id'],$r,$p);return[];}if($a==='delete'){$this->conflict($this->db->exec('UPDATE users SET active=0,deleted_at=?,version=version+1 WHERE id=? AND version=?',[Util::now(),$r['id'],(int)$p['version']]));$this->audit->log($u,'DELETE','user',$r['id'],$r,[]);return[];}throw new ApiException('ROUTE','Неизвестное действие');});}
}
